window.READ_TEXTS = (window.READ_TEXTS || []).concat([
  { t: 'Озеро Байкал', w: 'Байкал — самое глубокое озеро на планете. Его глубина достигает 1642 метров. Если поставить на дно несколько высоких башен одну на другую, они всё равно не достанут до поверхности. Байкал находится в Сибири, и ему около 25 миллионов лет. В озеро впадает больше трёхсот рек, а вытекает только одна — Ангара. Вода в Байкале такая чистая и прозрачная, что камни на дне видно на глубине сорока метров. Зимой озеро покрывается толстым льдом, и по нему даже ездят машины. Лёд бывает таким прозрачным, что сквозь него видно воду и пузырьки воздуха. Здесь живёт байкальская нерпа — единственный тюлень, который обитает в пресной воде озера. Нерпята рождаются белыми и пушистыми, а мамы прячут их в снежных норках на льду.', q: [
    { type: 'input', q: 'Какая глубина Байкала (в метрах)?', c: 1642 },
    { type: 'one', q: 'Какая река вытекает из Байкала?', a: ['Лена', 'Ангара', 'Енисей', 'Обь'], c: 1 },
    { type: 'one', q: 'Где нерпы прячут своих малышей?', a: ['В дуплах деревьев', 'На дне озера', 'В снежных норках на льду', 'В камышах'], c: 2 },
    { type: 'tf', q: 'Камни на дне Байкала видно на глубине сорока метров.', c: true } ] },

  { t: 'Муравьи-силачи', w: 'Муравей совсем крошечный, но он настоящий силач. Он может поднять и унести груз, который в 20 раз тяжелее его самого, а иногда и больше. Если бы человек был таким же сильным, он легко носил бы на спине легковую машину. Муравьи живут большими семьями в муравейниках. Главная в семье — царица. Она откладывает яйца, а остальные муравьи строят дом, добывают еду и ухаживают за малышами. Ушей у муравьёв нет. Они чувствуют дрожание земли лапками, а общаются запахами. Когда муравей находит еду, он возвращается домой и оставляет за собой пахучую дорожку. Другие муравьи идут по этому запаху и быстро находят добычу. Поэтому муравьи часто ходят друг за другом цепочкой. Муравейник в лесу может быть выше метра, а под землёй у него ещё много этажей.', q: [
    { type: 'input', q: 'Во сколько раз груз может быть тяжелее муравья?', c: 20 },
    { type: 'one', q: 'Кто откладывает яйца в муравейнике?', a: ['Все муравьи по очереди', 'Самый старый муравей', 'Царица', 'Муравьи-строители'], c: 2 },
    { type: 'one', q: 'Как муравьи показывают дорогу к еде?', a: ['Оставляют пахучую дорожку', 'Громко стрекочут', 'Машут усиками', 'Рисуют на земле'], c: 0 } ] },

  { t: 'Следы на Луне', w: 'Луна — наш ближайший сосед в космосе. До неё примерно 384 тысячи километров. Летом 1969 года на Луну впервые ступил человек — американский астронавт Нил Армстронг. Вместе с ним по Луне гулял Базз Олдрин. Всего на Луне побывали 12 человек. На Луне нет воздуха, поэтому там нет ветра и дождя. Следы астронавтов на лунной пыли сохранились до сих пор и могут пролежать миллионы лет. Притяжение на Луне в шесть раз слабее, чем на Земле. Поэтому астронавты передвигались смешными прыжками, как кенгуру, и легко поднимали тяжёлые вещи. Небо на Луне всегда чёрное, даже днём. А ещё Луна всегда повёрнута к Земле одной и той же стороной, и обратную сторону Луны люди увидели только на фотографиях, снятых космическими аппаратами.', q: [
    { type: 'input', q: 'Сколько всего человек побывали на Луне?', c: 12 },
    { type: 'one', q: 'Кто первым ступил на Луну?', a: ['Юрий Гагарин', 'Базз Олдрин', 'Нил Армстронг', 'Алексей Леонов'], c: 2 },
    { type: 'one', q: 'Во сколько раз притяжение на Луне слабее земного?', a: ['В два раза', 'В шесть раз', 'В десять раз', 'В сто раз'], c: 1 },
    { type: 'tf', q: 'Небо на Луне днём голубое, как на Земле.', c: false } ] },

  { t: 'Поехали!', w: 'Двенадцатого апреля 1961 года с космодрома Байконур стартовала ракета. На её вершине в корабле «Восток» сидел лётчик Юрий Гагарин. Ему было 27 лет. Перед стартом он весело сказал: «Поехали!» — и махнул рукой. Это слово запомнил весь мир. Полёт длился 108 минут. За это время Гагарин облетел вокруг всей Земли один раз. Он смотрел в иллюминатор и рассказывал по радио, как красива наша планета из космоса и какая она голубая. Приземлился Гагарин недалеко от города Саратова. Перед посадкой он катапультировался и опустился на парашюте прямо в поле. Первыми его встретили местная жительница и её внучка, которые очень удивились человеку в оранжевом скафандре. С тех пор двенадцатое апреля у нас празднуют как День космонавтики.', q: [
    { type: 'input', q: 'Сколько минут длился полёт Гагарина?', c: 108 },
    { type: 'input', q: 'Сколько лет было Гагарину во время полёта?', c: 27 },
    { type: 'one', q: 'Как назывался корабль Гагарина?', a: ['«Союз»', '«Восток»', '«Мир»', '«Буран»'], c: 1 },
    { type: 'one', q: 'Кто первым встретил Гагарина после посадки?', a: ['Женщина с внучкой', 'Отряд солдат', 'Другие космонавты', 'Журналисты'], c: 0 } ] },

  { t: 'История светофора', w: 'Первый светофор появился в Лондоне в 1868 году, задолго до автомобилей. Он помогал каретам и пешеходам на улице возле здания парламента. Днём у него поднимались и опускались специальные стрелки, а вечером зажигались газовые фонари красного и зелёного цвета. Управлял этим светофором полицейский, который поворачивал рычаг вручную. Электрический светофор изобрели позже, в 1914 году в Америке. Сначала у него было только два цвета, а жёлтый свет добавили потом, чтобы водители успевали подготовиться к остановке. В нашей стране первый светофор заработал в Москве в 1930 году на углу улицы Петровки и Кузнецкого моста. Сегодня светофоры бывают с таймером, со звуковым сигналом для незрячих людей и даже со смешными человечками, которые шагают на зелёном экране.', q: [
    { type: 'one', q: 'Где появился самый первый светофор?', a: ['В Москве', 'В Париже', 'В Лондоне', 'В Нью-Йорке'], c: 2 },
    { type: 'tf', q: 'Первым светофором управлял полицейский вручную.', c: true },
    { type: 'input', q: 'В каком году заработал первый светофор в Москве?', c: 1930 },
    { type: 'one', q: 'Зачем добавили жёлтый свет?', a: ['Для красоты', 'Чтобы водители успевали подготовиться', 'Чтобы светофор был ярче', 'Для пешеходов ночью'], c: 1 } ] },

  { t: 'Олимпийские игры', w: 'Олимпийские игры придумали в Древней Греции почти три тысячи лет назад. Соревнования проходили в местечке Олимпия, отсюда и название. Спортсмены бегали, прыгали, метали диск и копьё, боролись и устраивали гонки на колесницах. Победителю дарили не медаль, а венок из веток оливы. На время игр в Греции прекращались все войны, чтобы люди могли спокойно добраться до Олимпии. Потом игры надолго забыли. Возродил их француз Пьер де Кубертен, и первые современные Олимпийские игры прошли в Афинах в 1896 году. Символ игр — пять переплетённых колец: голубое, жёлтое, чёрное, зелёное и красное. Они означают пять частей света, которые объединяет спорт. Кубертен говорил, что на белом фоне эти цвета есть во флаге любой страны мира.', q: [
    { type: 'one', q: 'Что получал победитель в Древней Греции?', a: ['Золотую медаль', 'Мешок монет', 'Оливковый венок', 'Кубок'], c: 2 },
    { type: 'input', q: 'В каком году прошли первые современные Олимпийские игры?', c: 1896 },
    { type: 'one', q: 'Кто возродил Олимпийские игры?', a: ['Пьер де Кубертен', 'Древний царь Греции', 'Английский король', 'Итальянский художник'], c: 0 },
    { type: 'tf', q: 'Во время древних игр войны продолжались как обычно.', c: false } ] },

  { t: 'Почему хлеб пышный', w: 'Почему хлеб внутри мягкий и весь в дырочках? Всё дело в дрожжах. Дрожжи — это живые грибки, такие крошечные, что разглядеть один можно только в микроскоп. Когда пекарь замешивает тесто из муки, тёплой воды и щепотки сахара, дрожжи просыпаются и начинают есть сахар. При этом они выпускают углекислый газ. Газ собирается в пузырьки, тесто поднимается и становится в два раза больше. В горячей духовке пузырьки ещё немного раздуваются, а потом тесто застывает. Так в мякише и остаются дырочки. Если налить слишком горячую воду, дрожжи погибнут, и хлеб получится плоским и твёрдым. А если слишком холодную, они будут работать очень медленно. Люди пекли пышный хлеб ещё в Древнем Египте, хотя тогда никто не знал, что в тесте трудятся микроскопические грибки.', q: [
    { type: 'one', q: 'Что такое дрожжи?', a: ['Сорт муки', 'Живые крошечные грибки', 'Пищевая соль', 'Семена растения'], c: 1 },
    { type: 'one', q: 'Что выпускают дрожжи, когда едят сахар?', a: ['Углекислый газ', 'Воду', 'Масло', 'Кислород'], c: 0 },
    { type: 'tf', q: 'Слишком горячая вода помогает дрожжам работать быстрее.', c: false },
    { type: 'one', q: 'Где пекли пышный хлеб в древности?', a: ['В Древнем Египте', 'В Антарктиде', 'На Луне', 'Только в наши дни'], c: 0 } ] },

  { t: 'Откуда берётся радуга', w: 'Радуга появляется, когда одновременно светит солнце и идёт дождь. Солнечный свет кажется нам белым, но на самом деле в нём спрятаны все цвета. Когда луч попадает в круглую каплю воды, он преломляется, то есть меняет направление, и распадается на цвета. Миллионы капель вместе рисуют на небе разноцветную дугу. Чтобы увидеть радугу, нужно встать спиной к солнцу. Поэтому утром радугу видно на западе, а вечером — на востоке. Снаружи дуги всегда красный цвет, а внутри — фиолетовый. Запомнить порядок цветов помогает фраза: «Каждый охотник желает знать, где сидит фазан». Иногда на небе загорается двойная радуга. Во второй, бледной дуге цвета идут наоборот: красный оказывается внутри. Радугу можно сделать и самому: встань спиной к солнцу и распыли воду из садового шланга.', q: [
    { type: 'one', q: 'Как нужно встать, чтобы увидеть радугу?', a: ['Лицом к солнцу', 'Спиной к солнцу', 'Боком к дождю', 'Под деревом'], c: 1 },
    { type: 'one', q: 'Какой цвет снаружи радуги?', a: ['Фиолетовый', 'Зелёный', 'Синий', 'Красный'], c: 3 },
    { type: 'tf', q: 'Во второй дуге двойной радуги цвета идут в обратном порядке.', c: true },
    { type: 'one', q: 'Где видно радугу вечером?', a: ['На востоке', 'На западе', 'На юге', 'Прямо над головой'], c: 0 } ] },

  { t: 'Неутомимое сердце', w: 'Сожми руку в кулак — примерно такого размера твоё сердце. Оно находится в груди, чуть левее середины, и работает без остановки всю жизнь, даже когда ты спишь. Сердце — это мышца, которая работает как насос. Оно перекачивает кровь по всему телу. Кровь несёт кислород и питание к каждой клеточке, от макушки до кончиков пальцев на ногах. За сутки сердце сокращается около 100 тысяч раз. У детей сердце бьётся быстрее, чем у взрослых, а у новорождённых малышей — быстрее всего. Когда ты бегаешь или прыгаешь, мышцам нужно больше кислорода, и сердце стучит чаще. Свой пульс легко найти: приложи два пальца к запястью или к шее сбоку. Врач слушает сердце специальной трубкой — стетоскопом. Чтобы сердце было крепким, полезно много двигаться, гулять и играть на свежем воздухе.', q: [
    { type: 'one', q: 'С чем в тексте сравнивают размер сердца?', a: ['С яблоком', 'С кулаком', 'С арбузом', 'С горошиной'], c: 1 },
    { type: 'one', q: 'Сколько раз сердце сокращается за сутки?', a: ['Около 100 тысяч', 'Около 100', 'Около тысячи', 'Около миллиарда'], c: 0 },
    { type: 'tf', q: 'У детей сердце бьётся медленнее, чем у взрослых.', c: false },
    { type: 'one', q: 'Как называется трубка, которой врач слушает сердце?', a: ['Термометр', 'Микроскоп', 'Стетоскоп', 'Телескоп'], c: 2 } ] },

  { t: 'Долина гейзеров', w: 'На Камчатке, в Кроноцком заповеднике, есть удивительное место — Долина гейзеров. Гейзер — это горячий источник, который время от времени выбрасывает вверх струю кипятка и пара. Под землёй вода нагревается от раскалённых пород, закипает и с шумом вырывается наружу, как из огромного чайника. Потом гейзер затихает, набирает воду и через какое-то время снова «стреляет». Долину открыла в 1941 году молодая учёная Татьяна Устинова. Вместе с проводником она случайно заметила, как из берега реки бьёт фонтан горячей воды. Самый большой гейзер долины назвали Великаном. Его столб пара поднимается на сотни метров. Вокруг гейзеров растут ярко-зелёные мхи, а камни раскрашены в оранжевые, розовые и жёлтые цвета. Добраться сюда можно только на вертолёте, а гуляют туристы по деревянным дорожкам, чтобы не повредить хрупкую природу.', q: [
    { type: 'input', q: 'В каком году открыли Долину гейзеров?', c: 1941 },
    { type: 'one', q: 'Кто открыл Долину гейзеров?', a: ['Татьяна Устинова', 'Юрий Гагарин', 'Иван Фёдоров', 'Местный рыбак'], c: 0 },
    { type: 'one', q: 'Как называется самый большой гейзер долины?', a: ['Богатырь', 'Великан', 'Фонтан', 'Чайник'], c: 1 },
    { type: 'tf', q: 'В Долину гейзеров можно доехать на автобусе.', c: false } ] },

  { t: 'Бабочки-путешественницы', w: 'Бабочка монарх живёт в Северной Америке. У неё яркие оранжевые крылья с чёрными прожилками и белыми точками. Каждую осень миллионы монархов улетают из Канады и США на юг, в горы Мексики. Их путь длиной до 4000 километров! Хрупкая бабочка пролетает его сама, без карты и без родителей. Учёные считают, что монархам помогают солнце и магнитное поле Земли. В Мексике бабочки зимуют в хвойных лесах. Они облепляют стволы и ветки так плотно, что деревья кажутся оранжевыми. Гусеницы монарха едят только листья растения ваточника. В нём есть горький сок, поэтому и гусеницы, и бабочки становятся невкусными для птиц. Яркая окраска как будто предупреждает: «Не трогай меня!» Весной монархи летят обратно на север, и по дороге рождаются новые поколения бабочек.', q: [
    { type: 'input', q: 'Сколько километров может быть путь монархов?', c: 4000 },
    { type: 'one', q: 'Куда осенью улетают монархи?', a: ['В Африку', 'В горы Мексики', 'В Сибирь', 'В Австралию'], c: 1 },
    { type: 'one', q: 'Чем питаются гусеницы монарха?', a: ['Листьями ваточника', 'Листьями дуба', 'Нектаром роз', 'Травой'], c: 0 },
    { type: 'tf', q: 'Птицы очень любят есть бабочек монархов.', c: false } ] },

  { t: 'Тайны снежинок', w: 'Снежинки рождаются высоко в облаках. Крошечная капелька воды замерзает вокруг пылинки и превращается в кристаллик льда. Пока он падает, к нему прилипают новые льдинки, и вырастают лучи. У настоящей снежинки всегда 6 лучей. Но узоры у всех разные, потому что каждая снежинка летит своим путём, через разный холод и разную влажность. В 1885 году американский фермер Уилсон Бентли впервые сфотографировал снежинку через микроскоп. Он так увлёкся, что за свою жизнь сделал больше пяти тысяч снимков и не нашёл двух одинаковых снежинок. Интересно, что лёд прозрачный, а снег кажется белым. Это потому, что множество крошечных кристаллов отражают свет во все стороны. Свежий снег на девять десятых состоит из воздуха, поэтому снежное одеяло хорошо укрывает растения от мороза.', q: [
    { type: 'input', q: 'Сколько лучей у настоящей снежинки?', c: 6 },
    { type: 'one', q: 'Кем был Уилсон Бентли?', a: ['Фермером', 'Космонавтом', 'Художником', 'Королём'], c: 0 },
    { type: 'input', q: 'В каком году Бентли впервые сфотографировал снежинку?', c: 1885 },
    { type: 'tf', q: 'Свежий снег в основном состоит из воздуха.', c: true } ] },

  { t: 'Жираф', w: 'Жираф — самое высокое животное на Земле. Вместе с шеей он бывает ростом почти с двухэтажный дом. Живёт жираф в саваннах Африки и ест листья с высоких деревьев, особенно с колючей акации. Удивительно, но в его длинной шее столько же позвонков, сколько у человека и у мыши, — всего 7. Просто каждый позвонок очень большой. Язык у жирафа длиной почти полметра и тёмно-фиолетового цвета. Учёные думают, что тёмный цвет защищает язык от солнечных ожогов, ведь жираф постоянно держит его снаружи, когда обрывает листья. Спит жираф очень мало, часто стоя, урывками по несколько минут. А вот пить ему неудобно: приходится широко расставлять передние ноги и низко наклоняться к воде. Детёныш жирафа рождается высоким и уже через час встаёт на ноги и идёт за мамой.', q: [
    { type: 'input', q: 'Сколько позвонков в шее жирафа?', c: 7 },
    { type: 'one', q: 'Какого цвета язык у жирафа?', a: ['Розовый', 'Тёмно-фиолетовый', 'Жёлтый', 'Белый'], c: 1 },
    { type: 'one', q: 'Листья какого дерева особенно любит жираф?', a: ['Берёзы', 'Акации', 'Ели', 'Пальмы'], c: 1 },
    { type: 'tf', q: 'Детёныш жирафа встаёт на ноги через час после рождения.', c: true } ] },

  { t: 'Слоновий хобот', w: 'Хобот слона — это нос и верхняя губа, сросшиеся вместе. В нём десятки тысяч маленьких мышц, и в хоботе нет ни одной косточки. Слон умеет делать хоботом почти всё. Он срывает ветки, поднимает брёвна, гладит слонёнка и здоровается с друзьями. Кончиком хобота слон может аккуратно поднять даже орешек. Пьёт слон тоже с помощью хобота: набирает около 8 литров воды, а потом выливает её себе в рот. В жару он поливает себя водой или посыпает пылью, чтобы спастись от солнца. Большие уши тоже помогают охлаждаться: слон обмахивается ими, как веером. Слоны умеют разговаривать очень низкими звуками, которые человек не слышит. Эти звуки расходятся по земле на несколько километров, и другие слоны чувствуют их ногами. За день взрослый слон съедает больше ста килограммов травы и веток.', q: [
    { type: 'input', q: 'Сколько литров воды набирает слон в хобот?', c: 8 },
    { type: 'one', q: 'Из чего состоит хобот?', a: ['Из носа и верхней губы', 'Из языка', 'Из ушей', 'Из костей'], c: 0 },
    { type: 'one', q: 'Как слоны чувствуют низкие звуки сородичей?', a: ['Ногами', 'Хвостом', 'Глазами', 'Бивнями'], c: 0 },
    { type: 'tf', q: 'Слон обмахивается ушами, чтобы охладиться.', c: true } ] },

  { t: 'Настоящий Винни-Пух', w: 'Книгу о Винни-Пухе написал английский писатель Алан Милн. Главного героя он придумал не просто так. У его сына Кристофера Робина был плюшевый медвежонок, которого мальчику подарили на первый день рождения. А имя для игрушки мальчик взял у настоящей медведицы Виннипег из Лондонского зоопарка. Её привёз из Канады солдат, и медведица была такой доброй, что дети катались у неё на спине. Друзья Пуха — тоже игрушки Кристофера: ослик Иа, поросёнок Пятачок, Тигра, Кенга и малыш Ру. Сова и Кролик появились из фантазии писателя. В нашей стране Винни-Пуха пересказал поэт Борис Заходер. Именно он придумал знаменитые «пыхтелки» и «шумелки». А в мультфильме Винни-Пух поёт голосом артиста Евгения Леонова. Старые игрушки Кристофера Робина до сих пор хранятся в библиотеке Нью-Йорка.', q: [
    { type: 'one', q: 'Кто написал книгу о Винни-Пухе?', a: ['Борис Заходер', 'Алан Милн', 'Корней Чуковский', 'Евгений Леонов'], c: 1 },
    { type: 'one', q: 'В честь кого назвали игрушку?', a: ['В честь медведицы из зоопарка', 'В честь дедушки', 'В честь города', 'В честь собаки'], c: 0 },
    { type: 'tf', q: 'Сова и Кролик тоже были игрушками Кристофера Робина.', c: false },
    { type: 'one', q: 'Где сейчас хранятся старые игрушки?', a: ['В Лондонском зоопарке', 'В Москве', 'В библиотеке Нью-Йорка', 'Они потерялись'], c: 2 } ] },

  { t: 'Маленький принц', w: 'Сказку «Маленький принц» написал французский лётчик Антуан де Сент-Экзюпери. Книга вышла в 1943 году, и все рисунки в ней автор нарисовал сам. В сказке лётчик садится в пустыне Сахара из-за поломки самолёта и встречает необычного мальчика с золотыми волосами. Это Маленький принц, который прилетел с крошечной планеты — астероида Б-612. Его планета такая маленькая, что закат можно увидеть много раз за день, просто передвинув стул. Каждое утро принц выпалывает ростки баобабов, чтобы они не разрослись и не разорвали планету корнями. Дома у него осталась капризная, но любимая Роза. На Земле принц знакомится с Лисом, и тот открывает ему главный секрет: «Зорко одно лишь сердце. Самого главного глазами не увидишь». Книгу перевели на сотни языков, и её читают и дети, и взрослые.', q: [
    { type: 'input', q: 'В каком году вышла книга «Маленький принц»?', c: 1943 },
    { type: 'one', q: 'Кем был автор книги?', a: ['Моряком', 'Лётчиком', 'Учителем', 'Садовником'], c: 1 },
    { type: 'one', q: 'Чьи ростки выпалывал принц каждое утро?', a: ['Роз', 'Кактусов', 'Баобабов', 'Одуванчиков'], c: 2 },
    { type: 'tf', q: 'Секрет «Зорко одно лишь сердце» открыла принцу Роза.', c: false } ] },

  { t: 'Чудо-ребёнок Моцарт', w: 'Вольфганг Амадей Моцарт родился в 1756 году в австрийском городе Зальцбурге. Его отец был музыкантом и учил старшую сестру Вольфганга играть на клавесине. Малыш сидел рядом, слушал и вскоре сам начал подбирать мелодии. Свои первые пьесы он сочинил в 5 лет, когда ещё не умел толком писать ноты. В шесть лет Вольфганг вместе с сестрой поехал выступать по городам Европы. Публика ахала: мальчик играл с завязанными глазами и даже на клавишах, накрытых платком. Однажды в Риме четырнадцатилетний Моцарт один раз послушал сложное церковное песнопение, которое запрещали переписывать, а потом записал его по памяти почти без ошибок. За свою недолгую жизнь Моцарт сочинил больше 600 произведений: оперы, симфонии, концерты. Его весёлую и светлую музыку слушают и сегодня по всему миру.', q: [
    { type: 'input', q: 'Во сколько лет Моцарт сочинил первые пьесы?', c: 5 },
    { type: 'one', q: 'В каком городе родился Моцарт?', a: ['В Вене', 'В Риме', 'В Зальцбурге', 'В Париже'], c: 2 },
    { type: 'one', q: 'Что Моцарт сделал в Риме?', a: ['Записал песнопение по памяти', 'Построил театр', 'Выиграл скачки', 'Нарисовал картину'], c: 0 },
    { type: 'tf', q: 'Моцарт умел играть на клавишах, накрытых платком.', c: true } ] },

  { t: 'Самое глубокое место', w: 'Самое глубокое место на Земле находится в Тихом океане. Это Марианская впадина — огромная трещина на дне океана. Её глубина почти 11 километров. Если опустить туда самую высокую гору, Эверест, над его вершиной ещё осталось бы больше двух километров воды. На дне впадины вечная темнота и холод, а вода давит с огромной силой. Обычная подводная лодка туда не опустится. В 1960 году на дно впадины спустились 2 смелых исследователя — Жак Пикар и Дон Уолш. Их специальный аппарат назывался «Триест», и погружение заняло почти пять часов. А в 2012 году туда в одиночку опустился кинорежиссёр Джеймс Камерон. Удивительно, но даже на такой глубине есть жизнь: учёные нашли там маленьких рачков и необычных существ, которые никогда не видят солнечного света.', q: [
    { type: 'one', q: 'В каком океане находится Марианская впадина?', a: ['В Атлантическом', 'В Тихом', 'В Индийском', 'В Северном Ледовитом'], c: 1 },
    { type: 'input', q: 'Сколько исследователей спустились на дно в 1960 году?', c: 2 },
    { type: 'one', q: 'Как назывался их аппарат?', a: ['«Наутилус»', '«Триест»', '«Титаник»', '«Восток»'], c: 1 },
    { type: 'tf', q: 'На дне впадины учёные не нашли никакой жизни.', c: false } ] },

  { t: 'Синий кит', w: 'Синий кит — самое большое животное, которое когда-либо жило на Земле. Он больше любого динозавра! Длина синего кита бывает до 30 метров, это как три автобуса подряд. Только язык у него весит столько же, сколько целый слон, а сердце размером с небольшой автомобиль. Но питается этот великан крошечными рачками — крилем. Зубов у синего кита нет. Вместо них во рту растут пластины китового уса, похожие на густую расчёску. Кит набирает в пасть огромный глоток воды с рачками, а потом выталкивает воду языком. Вода выходит через ус, а криль остаётся внутри. За день кит съедает до 4 тонн криля. Детёныш синего кита пьёт мамино молоко и каждый день прибавляет почти сто килограммов. Синие киты поют низкими голосами, и их песни слышны под водой за сотни километров.', q: [
    { type: 'input', q: 'До скольких метров бывает длина синего кита?', c: 30 },
    { type: 'one', q: 'Чем питается синий кит?', a: ['Акулами', 'Водорослями', 'Крошечными рачками — крилем', 'Медузами'], c: 2 },
    { type: 'one', q: 'Что растёт у кита во рту вместо зубов?', a: ['Китовый ус', 'Щупальца', 'Шипы', 'Ничего'], c: 0 },
    { type: 'input', q: 'Сколько тонн криля кит съедает за день?', c: 4 } ] },

  { t: 'Живые фонарики', w: 'Тёплой летней ночью в траве иногда загораются маленькие зелёные огоньки. Это светлячки. Несмотря на название, светлячки — не мухи, а жуки. Свет появляется у них в брюшке, где происходит особая химическая реакция. Удивительно, что этот свет почти не нагревается, поэтому его называют холодным светом. Обычная лампочка тратит много энергии на тепло, а светлячок — почти всю на свет. Светлячки мигают не просто так. У каждого вида свой узор вспышек, будто азбука Морзе. По этим сигналам жуки находят друг друга в темноте. В некоторых странах тысячи светлячков вспыхивают одновременно, и лес мерцает, как новогодняя ёлка. Светятся даже личинки и яйца некоторых светлячков. В России светлячков в старину называли ивановыми червячками, потому что их много бывает около праздника Ивана Купалы в начале лета.', q: [
    { type: 'one', q: 'Кем на самом деле являются светлячки?', a: ['Мухами', 'Жуками', 'Бабочками', 'Червями'], c: 1 },
    { type: 'one', q: 'Почему их свет называют холодным?', a: ['Он почти не нагревается', 'Он голубой', 'Светлячки живут на севере', 'Он светит только зимой'], c: 0 },
    { type: 'one', q: 'Как в старину называли светлячков в России?', a: ['Ночными искрами', 'Ивановыми червячками', 'Лесными свечками', 'Звёздочками'], c: 1 },
    { type: 'tf', q: 'У всех видов светлячков одинаковый узор вспышек.', c: false } ] },

  { t: 'Гром и молния', w: 'Во время грозы в туче сталкиваются капли воды и кусочки льда. От этого в туче копится электричество, и в какой-то момент оно проскакивает огромной искрой — молнией. Молния очень горячая: она нагревает воздух примерно до 30 тысяч градусов. Это в пять раз жарче, чем поверхность Солнца! Воздух вокруг молнии мгновенно расширяется и создаёт громкий хлопок — гром. Свет летит гораздо быстрее звука, поэтому сначала мы видим вспышку, а уже потом слышим раскаты. Есть простой способ узнать, далеко ли гроза. Увидев молнию, начни считать секунды до грома. Звук пролетает один километр примерно за 3 секунды. Значит, если ты насчитал девять секунд, гроза в трёх километрах. Во время грозы лучше находиться дома, а на улице нельзя прятаться под одиноким высоким деревом.', q: [
    { type: 'one', q: 'Во сколько раз молния жарче поверхности Солнца?', a: ['В два раза', 'В пять раз', 'В десять раз', 'Она холоднее'], c: 1 },
    { type: 'input', q: 'За сколько секунд звук пролетает один километр?', c: 3 },
    { type: 'tf', q: 'Сначала мы слышим гром, а потом видим молнию.', c: false },
    { type: 'one', q: 'Где нельзя прятаться во время грозы?', a: ['Дома', 'Под одиноким высоким деревом', 'В машине', 'В подъезде'], c: 1 } ] },

  { t: 'Зубы', w: 'Первые зубки появляются у малышей примерно в полгода. Всего у ребёнка вырастает 20 молочных зубов. Лет в шесть или семь они начинают по одному шататься и выпадать, а на их месте вырастают постоянные зубы. У взрослого человека постоянных зубов 32. Последние из них, зубы мудрости, иногда вырастают только к двадцати пяти годам, а у некоторых людей не появляются совсем. Снаружи зуб покрыт эмалью. Это самое твёрдое вещество в нашем теле, твёрже любой косточки. Но у эмали есть враг — микробы. Они питаются остатками сладкой еды и выделяют кислоту, которая разрушает зуб и делает в нём дырочку. Поэтому стоматологи советуют чистить зубы два раза в день, утром и вечером, по две минуты. А ещё полезно грызть морковку и яблоки: они немного очищают зубы и укрепляют дёсны.', q: [
    { type: 'input', q: 'Сколько молочных зубов вырастает у ребёнка?', c: 20 },
    { type: 'input', q: 'Сколько постоянных зубов у взрослого человека?', c: 32 },
    { type: 'one', q: 'Что является самым твёрдым веществом в теле?', a: ['Кость', 'Ноготь', 'Эмаль', 'Волос'], c: 2 },
    { type: 'tf', q: 'Зубы мудрости вырастают у всех людей в детстве.', c: false } ] },

  { t: 'Транссибирская магистраль', w: 'Транссибирская магистраль — самая длинная железная дорога в мире. Она соединяет Москву и Владивосток, а её длина 9288 километров. Строить её начали в 1891 году. Рабочие прокладывали рельсы через тайгу, горы и болота, строили мосты через огромные сибирские реки Обь, Енисей и Амур. Особенно трудно было вдоль берега Байкала: там пришлось пробить в скалах десятки тоннелей. Сейчас поезд из Москвы во Владивосток идёт почти неделю. За это время пассажиры успевают увидеть леса, степи, горы и Байкал. Часы в пути приходится постоянно переводить: когда в Москве полдень, во Владивостоке уже семь часов вечера. В Москве на Ярославском вокзале и во Владивостоке на вокзале стоят особые столбики, отмечающие начало и конец этой великой дороги.', q: [
    { type: 'input', q: 'Какая длина Транссибирской магистрали (в километрах)?', c: 9288 },
    { type: 'one', q: 'Какие города соединяет дорога?', a: ['Москву и Санкт-Петербург', 'Москву и Владивосток', 'Казань и Омск', 'Мурманск и Сочи'], c: 1 },
    { type: 'one', q: 'Сколько времени поезд идёт по всей дороге?', a: ['Один день', 'Почти неделю', 'Месяц', 'Три часа'], c: 1 },
    { type: 'tf', q: 'Вдоль Байкала строителям пришлось пробить десятки тоннелей.', c: true } ] },

  { t: 'Корабль пустыни', w: 'Верблюда называют кораблём пустыни. Он может идти по раскалённому песку много дней и почти не пить. Многие думают, что в горбе у верблюда хранится вода. На самом деле там запас жира. Когда еды нет, верблюд постепенно расходует жир, и горб становится мягким и свисает набок. Зато, найдя воду, верблюд может выпить около ста литров всего за несколько минут. Это целая ванна! Верблюды бывают одногорбые и двугорбые. Одногорбые живут в жарких пустынях Африки и Аравии, а двугорбые — в Азии, где зимой бывает сильный мороз. Во время песчаной бури верблюд закрывает ноздри, а глаза защищает двойной ряд длинных ресниц. Широкие мягкие подошвы не дают ногам проваливаться в песок. А ещё верблюды могут есть колючки, которые не станет жевать ни одно другое животное.', q: [
    { type: 'one', q: 'Что на самом деле хранится в горбе верблюда?', a: ['Вода', 'Жир', 'Воздух', 'Молоко'], c: 1 },
    { type: 'one', q: 'Где живут двугорбые верблюды?', a: ['В Африке', 'В Азии', 'В Австралии', 'В Антарктиде'], c: 1 },
    { type: 'tf', q: 'Во время бури верблюд может закрыть ноздри.', c: true },
    { type: 'one', q: 'Что защищает глаза верблюда от песка?', a: ['Очки', 'Двойной ряд ресниц', 'Густые брови', 'Шерсть на ушах'], c: 1 } ] },

  { t: 'Вершина мира', w: 'Эверест — самая высокая гора на Земле. Её высота 8849 метров над уровнем моря. Гора стоит в Гималаях, на границе Непала и Китая. Тибетцы называют её Джомолунгмой. На вершине очень холодно и дует сильный ветер, а воздуха так мало, что большинство альпинистов поднимаются туда с баллонами кислорода. Первыми на вершину взошли 29 мая 1953 года новозеландец Эдмунд Хиллари и его друг Тенцинг Норгей из народа шерпов. Шерпы живут в горах Непала и прекрасно знают горные тропы. На вершине Тенцинг оставил в снегу сладости, а Хиллари сфотографировал товарища с флагами. Интересно, что Эверест продолжает расти. Каждый год он становится выше на несколько миллиметров, потому что под Гималаями медленно движутся огромные плиты земной коры.', q: [
    { type: 'input', q: 'Какая высота Эвереста (в метрах)?', c: 8849 },
    { type: 'one', q: 'Кто вместе с Хиллари первым взошёл на Эверест?', a: ['Тенцинг Норгей', 'Нил Армстронг', 'Жак Пикар', 'Пьер де Кубертен'], c: 0 },
    { type: 'one', q: 'Что Тенцинг оставил на вершине?', a: ['Палатку', 'Сладости', 'Свой рюкзак', 'Письмо'], c: 1 },
    { type: 'tf', q: 'Эверест каждый год становится немного ниже.', c: false } ] },

  { t: 'Первые печатные книги', w: 'Раньше каждую книгу переписывали от руки. Монахи сидели над страницами месяцами, а иногда и годами. Книги были очень дорогими, и купить их могли только богатые люди. Всё изменилось около 1450 года, когда немецкий мастер Иоганн Гутенберг придумал печатный станок. Он отлил из металла отдельные буквы. Из них, как из кубиков, можно было собрать целую страницу, намазать её краской и сделать много одинаковых оттисков. Потом буквы разбирали и складывали новую страницу. В России первую точно датированную печатную книгу выпустили в Москве в 1564 году. Она называлась «Апостол», а сделал её первопечатник Иван Фёдоров со своим помощником Петром Мстиславцем. Работа над ней шла почти год. Сегодня в Москве Ивану Фёдорову стоит памятник, а его «Апостол» хранится в музеях и библиотеках.', q: [
    { type: 'one', q: 'Кто придумал печатный станок в Германии?', a: ['Иван Фёдоров', 'Иоганн Гутенберг', 'Моцарт', 'Пётр Мстиславец'], c: 1 },
    { type: 'input', q: 'В каком году вышел «Апостол» Ивана Фёдорова?', c: 1564 },
    { type: 'one', q: 'Из чего Гутенберг сделал отдельные буквы?', a: ['Из дерева', 'Из металла', 'Из глины', 'Из бумаги'], c: 1 },
    { type: 'tf', q: 'До изобретения печати книги были дешёвыми.', c: false } ] },

  { t: 'Первый телефонный звонок', w: 'Телефон изобрёл Александр Белл. Он родился в Шотландии, а потом переехал в Америку. Белл был учителем и помогал глухим детям учиться говорить. Его мама плохо слышала, поэтому Белл с детства интересовался тем, как устроен звук. Он мечтал передавать человеческий голос по проводам. В 1876 году Белл получил документ на своё изобретение, а вскоре произошёл первый настоящий телефонный разговор. Белл позвал своего помощника, который находился в соседней комнате: «Мистер Ватсон, идите сюда, я хочу вас видеть!» Ватсон прибежал и закричал, что ясно слышал каждое слово. Первые телефоны были огромными, а звонить можно было только туда, куда протянут провод. Позже появились телефонные станции, где девушки-телефонистки вручную соединяли абонентов. А сегодня у нас в кармане телефоны без всяких проводов.', q: [
    { type: 'input', q: 'В каком году Белл получил документ на изобретение?', c: 1876 },
    { type: 'one', q: 'Кем работал Белл?', a: ['Врачом', 'Учителем глухих детей', 'Моряком', 'Поваром'], c: 1 },
    { type: 'one', q: 'Как звали помощника Белла?', a: ['Ватсон', 'Холмс', 'Эдисон', 'Робин'], c: 0 },
    { type: 'tf', q: 'На первых телефонных станциях абонентов соединяли вручную.', c: true } ] },

  { t: 'Пирамида Хеопса', w: 'Великая пирамида в Египте построена для фараона Хеопса около четырёх с половиной тысяч лет назад. Она была такой высокой, что почти четыре тысячи лет оставалась самым высоким зданием на Земле. Сначала её высота была 146 метров, это как пятидесятиэтажный дом. Сейчас пирамида немного ниже, потому что верхушка разрушилась. Пирамиду сложили примерно из двух миллионов каменных блоков. Каждый блок весит больше, чем легковой автомобиль. Учёные считают, что камни перевозили по реке Нил на лодках, а потом затаскивали наверх по наклонным насыпям. Работали тысячи строителей. Снаружи пирамиду когда-то покрывали гладкие белые плиты, и она сверкала на солнце. В древности люди составили список семи чудес света. Пирамида Хеопса — единственное из них, которое сохранилось до наших дней.', q: [
    { type: 'input', q: 'Какой была первоначальная высота пирамиды (в метрах)?', c: 146 },
    { type: 'one', q: 'По какой реке перевозили камни?', a: ['По Волге', 'По Амазонке', 'По Нилу', 'По Дунаю'], c: 2 },
    { type: 'one', q: 'Чем когда-то была покрыта пирамида снаружи?', a: ['Золотом', 'Гладкими белыми плитами', 'Зелёной краской', 'Песком'], c: 1 },
    { type: 'tf', q: 'Пирамида Хеопса — единственное сохранившееся чудо света.', c: true } ] },

  { t: 'Медведь в берлоге', w: 'Осенью бурый медведь очень много ест: ягоды, орехи, рыбу, корешки. Он копит жир на зиму и становится толстым и круглым. Потом медведь находит укромное место под вывороченным деревом или в яме и устраивает берлогу. Он выстилает её мхом, сухой травой и ветками. Когда выпадает снег, берлогу заметает сверху, и получается тёплый домик. Медведь засыпает и спит до весны, иногда почти полгода. Всё это время он ничего не ест и не пьёт, а живёт за счёт запасённого жира. Сон у медведя чуткий, и его легко разбудить, поэтому зимой его нельзя тревожить. А в январе или феврале у медведицы прямо в берлоге рождаются медвежата. Они крошечные, слепые и весят всего около 500 граммов. Медвежата пьют мамино молоко и растут, а весной вместе с мамой выходят из берлоги.', q: [
    { type: 'one', q: 'Чем медведь выстилает берлогу?', a: ['Мхом, травой и ветками', 'Песком', 'Камнями', 'Перьями'], c: 0 },
    { type: 'input', q: 'Сколько граммов весит новорождённый медвежонок?', c: 500 },
    { type: 'one', q: 'Когда рождаются медвежата?', a: ['Летом', 'Осенью', 'В январе или феврале', 'В мае'], c: 2 },
    { type: 'tf', q: 'Во время зимнего сна медведь иногда выходит поесть.', c: false } ] },

  { t: 'Совиные секреты', w: 'Сова — ночная охотница, и у неё много удивительных способностей. Глаза совы огромные, но двигать ими она не может: они похожи на две трубочки и неподвижно сидят в черепе. Зато сова умеет поворачивать голову на 270 градусов, почти назад, и видит всё вокруг, не двигая телом. Слух у совы такой острый, что она находит мышку под снегом, даже не видя её. У многих сов одно ухо расположено чуть выше другого. Так они точно определяют, откуда доносится шорох. А ещё сова летает совершенно бесшумно. Края её перьев мягкие и бахромчатые, словно растрёпанная кисточка, и гасят шум крыльев. Мышь не слышит, как приближается охотница. Сова глотает добычу целиком, а потом выплёвывает комочек из шерсти и косточек. По таким комочкам учёные узнают, чем питаются совы.', q: [
    { type: 'input', q: 'На сколько градусов сова может повернуть голову?', c: 270 },
    { type: 'tf', q: 'Сова может свободно двигать глазами.', c: false },
    { type: 'one', q: 'Почему сова летает бесшумно?', a: ['Она очень лёгкая', 'У перьев мягкие бахромчатые края', 'Она редко машет крыльями', 'Она летает только в тумане'], c: 1 },
    { type: 'one', q: 'Зачем у совы одно ухо выше другого?', a: ['Чтобы точно найти, откуда шорох', 'Для красоты', 'Чтобы лучше видеть', 'Чтобы не мёрзнуть'], c: 0 } ] },

  { t: 'Как взрывается попкорн', w: 'Попкорн делают не из обычной кукурузы, а из особого сорта. У его зёрен очень твёрдая и прочная оболочка. Внутри каждого зёрнышка есть крахмал и крошечная капелька воды. Когда зерно нагревают на сковородке, вода превращается в пар. Пару некуда деться, ведь оболочка не пропускает его наружу. Давление внутри растёт, и примерно при 180 градусах оболочка не выдерживает и лопается с громким хлопком. Мягкий крахмал мгновенно раздувается, выворачивается наружу и застывает пушистым белым облачком. Так зёрнышко становится в десятки раз больше. Если зерно треснуло или пересохло, пар выходит раньше времени, и попкорн не получается. Такие нераскрывшиеся зёрна часто остаются на дне пакета. Древние жители Америки жарили попкорн тысячи лет назад и даже делали из него украшения.', q: [
    { type: 'one', q: 'Что прячется внутри зёрнышка, кроме крахмала?', a: ['Капелька воды', 'Сахар', 'Масло', 'Воздушный шарик'], c: 0 },
    { type: 'input', q: 'Примерно при скольких градусах лопается оболочка?', c: 180 },
    { type: 'tf', q: 'Попкорн можно сделать из любой кукурузы.', c: false },
    { type: 'one', q: 'Почему некоторые зёрна не раскрываются?', a: ['Они слишком большие', 'Они треснули или пересохли', 'Они слишком сладкие', 'Их мало жарили'], c: 1 } ] },

  { t: 'Почему лёд плавает', w: 'Почти все вещества, замерзая, становятся плотнее и тонут в своей жидкости. А вода ведёт себя по-особому. Когда она превращается в лёд, её частички выстраиваются в просторную решётку, и вода расширяется примерно на одну десятую. Поэтому лёд легче воды и плавает на поверхности. Это легко проверить: брось кубик льда в стакан, и он останется наверху. А если поставить в морозилку полную стеклянную бутылку с водой, лёд может её разорвать. Свойство льда очень важно для природы. Зимой реки и озёра замерзают сверху, а не со дна. Лёд, как одеяло, укрывает воду от мороза. Подо льдом у дна вода остаётся тёплой — около +4 градусов. Там спокойно зимуют рыбы, лягушки и раки. Если бы лёд тонул, водоёмы промерзали бы насквозь.', q: [
    { type: 'one', q: 'На какую часть расширяется вода при замерзании?', a: ['Примерно на одну десятую', 'В два раза', 'На половину', 'Не расширяется'], c: 0 },
    { type: 'tf', q: 'Реки и озёра замерзают со дна.', c: false },
    { type: 'input', q: 'Сколько градусов тепла остаётся у дна подо льдом?', c: 4 },
    { type: 'one', q: 'Что может случиться с полной бутылкой в морозилке?', a: ['Лёд может её разорвать', 'Вода исчезнет', 'Бутылка станет мягкой', 'Ничего'], c: 0 } ] },

  { t: 'Волшебная стрелка компаса', w: 'Наша планета — это огромный магнит. Вокруг неё есть невидимое магнитное поле. Стрелка компаса — маленький магнит, поэтому она всегда поворачивается одним концом на север, а другим на юг. Компас изобрели в Древнем Китае. Самый первый компас был похож на ложку из магнитного камня. Её клали на гладкую доску, и ручка ложки показывала на юг. Позже моряки стали подвешивать намагниченную иголку на нитке или класть её на кусочек пробки в миске с водой. С компасом корабли перестали теряться в открытом море, даже когда небо затянуто тучами и не видно ни солнца, ни звёзд. Интересно, что магнитный полюс Земли не стоит на месте, а медленно путешествует. А некоторые животные, например перелётные птицы и морские черепахи, чувствуют магнитное поле и находят по нему дорогу.', q: [
    { type: 'one', q: 'Где изобрели компас?', a: ['В Древнем Египте', 'В Древнем Китае', 'В Англии', 'В России'], c: 1 },
    { type: 'one', q: 'На что был похож самый первый компас?', a: ['На ложку', 'На часы', 'На ключ', 'На колокольчик'], c: 0 },
    { type: 'tf', q: 'Магнитный полюс Земли всегда стоит на одном месте.', c: false },
    { type: 'one', q: 'Кто из животных чувствует магнитное поле?', a: ['Кошки и собаки', 'Перелётные птицы и черепахи', 'Коровы и лошади', 'Никто'], c: 1 } ] },

  { t: 'Откуда пришли шахматы', w: 'Шахматы — одна из самых древних игр. Они появились в Индии примерно полторы тысячи лет назад. Первая игра называлась чатуранга, и фигуры в ней изображали армию: пехоту, конницу, колесницы и боевых слонов. Из Индии игра попала в Персию, а оттуда разошлась по всему миру. Слово «шах» по-персидски значит «король», а выражение «шах и мат» означает примерно «король беспомощен». На шахматной доске 64 клетки, а у каждого игрока по 16 фигур. Интересно, что ферзь, самая сильная фигура сегодня, в древности был одной из самых слабых и ходил всего на одну клетку наискосок. Есть старинная легенда: изобретатель шахмат попросил у царя награду — положить на первую клетку одно зёрнышко, на вторую два, на третью четыре и так далее. Оказалось, что столько зерна нет во всём мире!', q: [
    { type: 'one', q: 'Где появились шахматы?', a: ['В Китае', 'В Индии', 'В Греции', 'В Египте'], c: 1 },
    { type: 'input', q: 'Сколько клеток на шахматной доске?', c: 64 },
    { type: 'one', q: 'Что значит слово «шах» по-персидски?', a: ['Конь', 'Король', 'Слон', 'Победа'], c: 1 },
    { type: 'tf', q: 'В древности ферзь был самой сильной фигурой.', c: false } ] },

  { t: 'Наш скелет', w: 'Скелет — это опора нашего тела. Без него мы были бы мягкими, как медузы. Кости защищают важные органы: череп бережёт мозг, а рёбра — сердце и лёгкие. Удивительно, что у новорождённого малыша почти 300 косточек, а у взрослого человека — всего 206. Куда же деваются остальные? Они не пропадают, а срастаются друг с другом, пока ребёнок растёт. Больше половины всех костей находится в кистях рук и в стопах. Благодаря этому пальцы такие ловкие. Самая длинная кость — бедренная, она в ноге. А самая маленькая прячется в ухе и называется стремечко. Она размером с рисовое зёрнышко. Кости — живые, они растут и могут срастаться после перелома. Чтобы кости были крепкими, им нужен кальций из молока, творога и сыра, а ещё движение и прогулки на солнце.', q: [
    { type: 'input', q: 'Сколько костей у взрослого человека?', c: 206 },
    { type: 'one', q: 'Как называется самая маленькая кость?', a: ['Стремечко', 'Позвонок', 'Ребро', 'Мизинчик'], c: 0 },
    { type: 'one', q: 'Где находится больше половины всех костей?', a: ['В голове', 'В кистях рук и стопах', 'В спине', 'В груди'], c: 1 },
    { type: 'tf', q: 'Лишние кости малыша со временем срастаются друг с другом.', c: true } ] },

  { t: 'Полярная крачка', w: 'Полярная крачка — небольшая белая птица с чёрной шапочкой и красным клювом. Весит она около ста граммов, не больше яблока. Но эта малышка — настоящая чемпионка по дальним перелётам. Летом крачки выводят птенцов на севере, в Арктике. А когда там наступает осень, они улетают на другой конец планеты — в Антарктиду, где в это время начинается лето. Потом крачки возвращаются обратно. За год птица пролетает около 70 тысяч километров. Получается, что крачка встречает два лета в году и видит больше солнечного света, чем любое другое животное. Живут крачки больше тридцати лет. Учёные посчитали, что за всю жизнь одна птица пролетает расстояние, как от Земли до Луны и обратно три раза! Во время перелёта крачки ловят рыбу, ныряя в море, а иногда даже спят на лету.', q: [
    { type: 'one', q: 'Какого цвета клюв у полярной крачки?', a: ['Жёлтый', 'Чёрный', 'Красный', 'Белый'], c: 2 },
    { type: 'one', q: 'Куда улетают крачки из Арктики?', a: ['В Африку', 'В Антарктиду', 'В Сибирь', 'В Индию'], c: 1 },
    { type: 'tf', q: 'Полярная крачка встречает два лета в году.', c: true },
    { type: 'one', q: 'Сколько километров крачка пролетает за год?', a: ['Около 7 тысяч', 'Около 70 тысяч', 'Около 700', 'Около миллиона'], c: 1 } ] },

  { t: 'Наша звезда Солнце', w: 'Солнце — это звезда, такая же, как те, что мерцают на ночном небе. Просто оно гораздо ближе к нам, поэтому кажется большим и ярким. На самом деле Солнце — огромный раскалённый шар из газа. В поперечнике оно в 109 раз больше Земли. Внутрь Солнца поместилось бы больше миллиона таких планет, как наша. Температура на его поверхности около шести тысяч градусов, а в центре — миллионы градусов. Свет от Солнца летит к нам примерно 8 минут. Значит, мы всегда видим Солнце таким, каким оно было восемь минут назад. Без Солнца на Земле не было бы ни тепла, ни растений, ни животных. Солнцу около пяти миллиардов лет, и оно будет светить ещё очень-очень долго. Смотреть на Солнце без специальных тёмных фильтров нельзя: можно повредить глаза.', q: [
    { type: 'input', q: 'Во сколько раз Солнце в поперечнике больше Земли?', c: 109 },
    { type: 'input', q: 'Сколько минут свет летит от Солнца до Земли?', c: 8 },
    { type: 'one', q: 'Из чего состоит Солнце?', a: ['Из раскалённого газа', 'Из камня', 'Из льда', 'Из металла'], c: 0 },
    { type: 'tf', q: 'На Солнце можно смотреть без фильтров, это безопасно.', c: false } ] },

  { t: 'Паутина', w: 'Многие думают, что пауки — это насекомые. Но это не так! У насекомых шесть ног, а у пауков 8. Пауки относятся к другому классу животных — паукообразным. Главное умение паука — плести паутину. Шёлковая нить выходит из особых бугорков на конце брюшка, которые называются паутинными бородавками. Сначала нить жидкая, а на воздухе быстро застывает. Паутинка очень тонкая, но удивительно прочная. Она прочнее стальной проволоки такой же толщины и при этом хорошо тянется. Чтобы не прилипнуть к своей ловушке, паук бегает по специальным сухим нитям. Некоторые пауки каждый день плетут новую сеть, а старую съедают, чтобы не тратить шёлк зря. В конце лета маленькие паучки выпускают длинные паутинки, и ветер уносит их далеко-далеко, как на воздушном шаре.', q: [
    { type: 'input', q: 'Сколько ног у паука?', c: 8 },
    { type: 'tf', q: 'Пауки — это насекомые.', c: false },
    { type: 'one', q: 'Почему паук не прилипает к паутине?', a: ['Бегает по сухим нитям', 'Смазывает лапки маслом', 'Летает над ней', 'Он слишком лёгкий'], c: 0 },
    { type: 'one', q: 'Что некоторые пауки делают со старой паутиной?', a: ['Выбрасывают', 'Съедают', 'Дарят соседям', 'Оставляют навсегда'], c: 1 } ] },

  { t: 'Северное сияние', w: 'Зимой на далёком севере ночное небо иногда загорается разноцветными лентами. Они переливаются, колышутся, как занавески на ветру, и медленно меняют форму. Это северное сияние. Откуда оно берётся? Солнце постоянно выбрасывает в космос мельчайшие частички. Этот поток называют солнечным ветром. Когда частички долетают до Земли, магнитное поле планеты направляет их к полюсам. Высоко в небе, на высоте больше ста километров, частички сталкиваются с воздухом, и воздух начинает светиться. Чаще всего сияние бывает зелёным, реже красным, синим или фиолетовым. В России сиянием любуются в Мурманской области, на Таймыре, в Якутии и на Чукотке. Лучше всего его видно в морозную безоблачную ночь, вдали от фонарей. В старину люди придумывали о сиянии сказки, а теперь учёные даже составляют прогнозы, когда его можно увидеть.', q: [
    { type: 'one', q: 'Как называют поток частиц от Солнца?', a: ['Солнечный ветер', 'Звёздный дождь', 'Лунный свет', 'Космический снег'], c: 0 },
    { type: 'one', q: 'Каким чаще всего бывает северное сияние?', a: ['Жёлтым', 'Зелёным', 'Оранжевым', 'Белым'], c: 1 },
    { type: 'tf', q: 'Сияние лучше видно в облачную ночь рядом с фонарями.', c: false },
    { type: 'one', q: 'На какой высоте светится воздух?', a: ['Больше ста километров', 'Около одного метра', 'Около десяти метров', 'Под землёй'], c: 0 } ] },

  { t: 'Первая матрёшка', w: 'Матрёшка — самая известная русская игрушка, хотя придумали её не так уж давно, в конце девятнадцатого века. Говорят, что идею подсказала деревянная фигурка, которую привезли из Японии. Внутри неё пряталось ещё несколько фигурок. Русские мастера решили сделать свою игрушку. Её выточил из дерева токарь Василий Звёздочкин, а расписал художник Сергей Малютин. Первая матрёшка изображала круглолицую девушку в сарафане и платочке с чёрным петухом в руках. Внутри неё было спрятано 8 фигурок: девочки и мальчики, а самая маленькая изображала спелёнутого младенца. Назвали игрушку ласковым именем Матрёна, которое тогда было очень популярным. В 1900 году матрёшку показали на Всемирной выставке в Париже, и она получила медаль. С тех пор матрёшки разъехались по всему миру.', q: [
    { type: 'one', q: 'Кто расписал первую матрёшку?', a: ['Сергей Малютин', 'Василий Звёздочкин', 'Иван Фёдоров', 'Борис Заходер'], c: 0 },
    { type: 'input', q: 'Сколько фигурок было внутри первой матрёшки?', c: 8 },
    { type: 'one', q: 'Что держала в руках первая матрёшка?', a: ['Корзинку', 'Чёрного петуха', 'Букет цветов', 'Самовар'], c: 1 },
    { type: 'input', q: 'В каком году матрёшку показали на выставке в Париже?', c: 1900 } ] },

  // ===== v29: тексты с уровнем сложности lv (1 — 100–150 слов, 2 — 150–220, 3 — 220–300) =====
  { t: 'Ёж готовится к зиме', lv: 1, w: 'Ёж — ночной зверёк. Днём он спит в укромном месте, а вечером выходит на охоту. Ёж ест жуков, гусениц, дождевых червей и слизней. Когда он ищет еду в траве, то громко фыркает и пыхтит. На спине у ежа тысячи острых иголок. Если ёж испугается, он сворачивается в колючий шар, и врагу его не схватить. Осенью ёж много ест и становится толстым. Потом он строит гнездо из сухих листьев и травы и засыпает на всю зиму. Во время спячки его сердце бьётся очень медленно, а тело остывает. Весной ёж просыпается худым и голодным. Многие думают, что ежи носят на иголках яблоки. На самом деле так бывает только на картинках и в сказках. И ещё: молоко ежам давать нельзя, от него у них болит живот.', q: [
    { type: 'one', q: 'Чем питается ёж?', a: ['Только яблоками и грибами', 'Жуками, червями и слизнями', 'Травой и корой', 'Рыбой'], c: 1 },
    { type: 'one', q: 'Когда ёж выходит на охоту?', a: ['Рано утром', 'В полдень', 'Вечером', 'Только зимой'], c: 2 },
    { type: 'one', q: 'Из чего ёж строит гнездо для спячки?', a: ['Из сухих листьев и травы', 'Из глины', 'Из камней', 'Из перьев'], c: 0 },
    { type: 'tf', q: 'Ежам полезно давать молоко.', c: false } ] },

  { t: 'Подсолнух и солнце', lv: 1, w: 'Подсолнух получил своё имя не случайно. Молодой подсолнух, пока растёт, поворачивает голову вслед за солнцем. Утром он смотрит на восток, днём следит за солнцем по небу, а к вечеру поворачивается на запад. Ночью растение медленно возвращается обратно на восток и ждёт рассвета. Когда подсолнух вырастает и зацветает, он перестаёт вертеться. Взрослые цветы почти всегда смотрят на восток. Учёные выяснили, что так их утром быстрее согревает солнце, а к тёплым цветкам прилетает больше пчёл. Большая жёлтая «голова» подсолнуха — это не один цветок. Это сотни и даже тысячи крошечных цветочков, собранных вместе. Из каждого получается семечко. Из семечек делают подсолнечное масло, а зимой птицы с удовольствием клюют их в кормушках.', q: [
    { type: 'one', q: 'Куда смотрят взрослые цветущие подсолнухи?', a: ['На запад', 'На восток', 'На север', 'Вниз, в землю'], c: 1 },
    { type: 'one', q: 'Что делает молодой подсолнух ночью?', a: ['Поворачивается обратно на восток', 'Закрывается и опускает голову', 'Смотрит на запад', 'Ничего не делает'], c: 0 },
    { type: 'tf', q: 'Жёлтая «голова» подсолнуха — это один большой цветок.', c: false },
    { type: 'one', q: 'Почему взрослым подсолнухам выгодно смотреть на восток?', a: ['Так их не замечают птицы', 'Там меньше ветра', 'Утром их быстрее греет солнце, и прилетает больше пчёл', 'Так их легче поливать'], c: 2 } ] },

  { t: 'Морская звезда', lv: 1, w: 'Морская звезда живёт на дне моря. Обычно у неё пять лучей, но бывают звёзды с десятью, двадцатью и даже большим числом лучей. У морской звезды нет мозга и нет крови. Вместо крови по её телу течёт морская вода. На нижней стороне каждого луча — сотни крошечных ножек-присосок. С их помощью звезда медленно ползает по камням. А на кончике каждого луча есть простой глазок. Он не видит чётких картинок, но отличает свет от темноты. Морская звезда умеет делать удивительную вещь: если она потеряет луч, на его месте вырастет новый. Охотится звезда на ракушки. Она обхватывает раковину лучами и немного раскрывает её. Потом звезда выворачивает свой желудок наружу, прямо внутрь ракушки, и переваривает добычу.', q: [
    { type: 'input', q: 'Сколько лучей обычно у морской звезды?', c: 5 },
    { type: 'tf', q: 'У морской звезды есть мозг.', c: false },
    { type: 'one', q: 'Где у морской звезды глазки?', a: ['В центре спины', 'На кончиках лучей', 'На присосках', 'Глаз у неё нет'], c: 1 },
    { type: 'one', q: 'Что течёт по телу звезды вместо крови?', a: ['Морская вода', 'Сок водорослей', 'Масло', 'Чернила'], c: 0 } ] },

  { t: 'Зачем мы моргаем', lv: 1, w: 'Ты моргаешь много раз в минуту и даже не замечаешь этого. Обычно человек моргает примерно пятнадцать–двадцать раз в минуту. Одно моргание длится меньше секунды. Зачем это нужно? Глаз всё время должен быть влажным. Когда веко опускается, оно, как дворник на стекле машины, размазывает по глазу тонкий слой слезы. Слеза смывает пылинки и защищает глаз от микробов. Ресницы тоже помогают: они задерживают пыль и мошек. Если что-то быстро летит в лицо, глаза закрываются сами, мы даже не успеваем подумать. А вот когда мы смотрим в экран или читаем, то моргаем реже. Поэтому глаза устают и становятся сухими. Вот почему полезно делать перерывы, смотреть вдаль и иногда нарочно поморгать.', q: [
    { type: 'one', q: 'Сколько примерно раз в минуту моргает человек?', a: ['1–2 раза', '15–20 раз', '100–200 раз', 'Ни разу'], c: 1 },
    { type: 'one', q: 'С чем в тексте сравнивается веко?', a: ['С занавеской', 'С зонтиком', 'С дворником на стекле машины', 'С крышкой кастрюли'], c: 2 },
    { type: 'tf', q: 'Когда мы смотрим в экран, мы моргаем чаще.', c: false },
    { type: 'one', q: 'Что задерживают ресницы?', a: ['Пыль и мошек', 'Солнечный свет', 'Звуки', 'Слёзы'], c: 0 } ] },

  { t: 'Пассажиры воздушного шара', lv: 1, w: 'Больше двухсот лет назад во Франции жили братья Монгольфье. Они заметили, что дым от костра поднимается вверх. Братья решили сшить большой шар из ткани и бумаги и наполнить его горячим воздухом. Тёплый воздух легче холодного, поэтому шар полетел! В 1783 году братья устроили показ для короля. Под шаром висела корзина, а в ней сидели первые воздушные пассажиры: баран, утка и петух. Шар пролетел несколько минут и мягко опустился. Все животные остались живы и здоровы. Только после этого люди решились полететь сами. Через два месяца в небо поднялись первые воздухоплаватели. Сегодня на воздушных шарах летают ради красоты и спорта, а воздух в шаре греют газовой горелкой.', q: [
    { type: 'input', q: 'В каком году братья показали шар королю?', c: 1783 },
    { type: 'one', q: 'Кто были первыми пассажирами шара?', a: ['Кошка, собака и мышь', 'Сами братья', 'Баран, утка и петух', 'Король и королева'], c: 2 },
    { type: 'one', q: 'Чем братья наполнили шар?', a: ['Горячим воздухом', 'Холодным воздухом', 'Водой', 'Дымом от свечки'], c: 0 },
    { type: 'tf', q: 'Люди полетели на шаре через два месяца после показа с животными.', c: true } ] },

  { t: 'Золотая хохлома', lv: 2, w: 'Хохлома — старинный русский промысел из Нижегородской области. Так называется роспись по дереву: красные ягоды, листья и травы на чёрном и золотом фоне. Своё имя роспись получила от большого торгового села Хохлома. Туда мастера из окрестных деревень привозили на продажу расписные ложки, миски и ковши. Самое удивительное в хохломе — золото. Посуда сияет, будто сделана из драгоценного металла, но настоящего золота в ней нет! Мастер покрывает деревянную чашку глиняным раствором и олифой — особым маслом. Потом он натирает её серебристым металлическим порошком. Раньше для этого брали олово, а теперь берут алюминий. Затем мастер рисует узор кистью, покрывает изделие лаком и ставит в жаркую печь. От жара лак желтеет, и серебристый цвет превращается в золотой. Кисти для росписи мастера раньше делали сами, например из беличьих хвостов. Роспись бывает «верховой», когда узор рисуют прямо по золотому фону, и «фоновой», когда золотым остаётся только рисунок, а фон закрашивают чёрной или красной краской. Чаще всего на посуде рисуют ягоды рябины, клубники и смородины и тонкие завитки, которые мастера называют «травкой». Узоры рисуют от руки, без трафарета, поэтому двух совсем одинаковых чашек не бывает. Сегодня хохломскую посуду знают во многих странах мира.', q: [
    { type: 'one', q: 'Какой металл сейчас используют, чтобы посуда стала «золотой»?', a: ['Золото', 'Медь', 'Алюминий', 'Железо'], c: 2 },
    { type: 'tf', q: 'В хохломской посуде есть настоящее золото.', c: false },
    { type: 'one', q: 'Почему серебристый цвет превращается в золотой?', a: ['Мастер красит его жёлтой краской', 'Лак желтеет от жара в печи', 'Металл ржавеет', 'Посуду натирают мёдом'], c: 1 },
    { type: 'one', q: 'Откуда роспись получила своё название?', a: ['От торгового села Хохлома', 'От имени первого мастера', 'От названия реки', 'От слова «хохотать»'], c: 0 } ] },

  { t: 'Как работает холодильник', lv: 2, w: 'Холодильник есть почти в каждом доме, но мало кто знает, как он работает. Оказывается, он не делает холод, а уносит тепло из камеры наружу. По трубкам холодильника бежит особое вещество — хладагент. Внутри камеры он испаряется, то есть превращается из жидкости в газ. При испарении вещество забирает тепло. Ты это чувствовал сам: когда выходишь из воды после купания, мокрой коже прохладно, потому что вода испаряется. Затем насос-компрессор сжимает газ и гонит его в трубки снаружи, обычно на задней стенке. Там газ отдаёт тепло воздуху в комнате и снова становится жидкостью. И всё начинается сначала. Поэтому сзади холодильник тёплый, а внутри холодный. Внутри холодильника есть термостат — датчик, который следит за температурой. Когда в камере становится достаточно холодно, он выключает компрессор, а когда теплеет — включает снова. Поэтому холодильник то тихо гудит, то затихает. Дверцу не стоит держать открытой надолго: тёплый воздух из кухни заходит внутрь, и холодильнику приходится работать больше. До изобретения холодильников продукты хранили в погребах-ледниках. Лёд для них зимой выпиливали на реке.', q: [
    { type: 'one', q: 'Что на самом деле делает холодильник?', a: ['Делает холод из воздуха', 'Уносит тепло из камеры наружу', 'Охлаждает продукты снегом', 'Замораживает воду из крана'], c: 1 },
    { type: 'one', q: 'Как называется вещество, которое бежит по трубкам?', a: ['Хладагент', 'Антифриз', 'Пар', 'Рассол'], c: 0 },
    { type: 'tf', q: 'Задняя стенка работающего холодильника обычно тёплая.', c: true },
    { type: 'one', q: 'Где хранили продукты до изобретения холодильников?', a: ['На чердаке', 'В печке', 'В погребах-ледниках', 'В сундуках'], c: 2 } ] },

  { t: 'Годичные кольца', lv: 2, w: 'Если посмотреть на спил дерева, видно много колец, одно внутри другого. Их называют годичными кольцами. Каждый год ствол становится немного толще, и нарастает новое кольцо. Весной и в начале лета дерево растёт быстро, и древесина получается светлой и широкой. К концу лета рост замедляется, и появляется тонкая тёмная полоска. Светлая и тёмная полоски вместе — это один год жизни дерева. Чтобы узнать возраст дерева, надо сосчитать тёмные кольца. Кольца рассказывают и о погоде. В тёплый и влажный год кольцо выходит широким, а в засуху или холод — узким. Учёные, которые изучают кольца деревьев, по старым брёвнам узнают, какая погода была сотни лет назад. А по брёвнам из старинных домов можно определить, в каком году срубили деревья для постройки. Науку о годичных кольцах называют дендрохронологией. Это длинное слово сложено из трёх греческих: «дерево», «время» и «учение». Чтобы узнать возраст живого дерева, его не нужно пилить. Специальным тонким буром из ствола берут узкий столбик древесины и считают кольца на нём.', q: [
    { type: 'one', q: 'Что означает одно годичное кольцо (светлая и тёмная полоски вместе)?', a: ['Один месяц', 'Один год жизни дерева', 'Одну ветку', 'Одну зиму без снега'], c: 1 },
    { type: 'tf', q: 'В засуху годичное кольцо получается широким.', c: false },
    { type: 'one', q: 'Как узнать возраст живого дерева, не спиливая его?', a: ['Посчитать листья', 'Измерить высоту', 'Взять буром тонкий столбик древесины', 'Посчитать шишки'], c: 2 },
    { type: 'one', q: 'Когда древесина растёт светлой и широкой?', a: ['Весной и в начале лета', 'Зимой', 'Поздней осенью', 'Только ночью'], c: 0 } ] },

  { t: 'Дом на орбите', lv: 2, w: 'Международная космическая станция — это огромный дом, который летает вокруг Земли. Её собирали прямо в космосе, как конструктор, из отдельных частей — модулей. Первый модуль, «Заря», запустили в 1998 году. Строили станцию вместе разные страны: Россия, США, Япония, Канада и страны Европы. Станция летит на высоте около четырёхсот километров. Это гораздо ближе, чем Луна, но намного выше любого самолёта. Скорость у станции огромная: один оборот вокруг Земли она делает примерно за полтора часа. Поэтому космонавты за сутки видят около 16 восходов и закатов! На станции всё парит в невесомости: и люди, и капли воды, и крошки. Спят космонавты в спальных мешках, пристёгнутых к стене, чтобы не улетать во сне. Привычного душа на станции нет: космонавты обтираются влажными полотенцами, а волосы моют особым шампунем, который не нужно смывать. Хлеб для них пекут крошечными буханочками на один укус, чтобы крошки не разлетались. Каждый день они по два часа занимаются на специальных тренажёрах, иначе мышцы и кости ослабнут. Станцию можно увидеть с Земли без телескопа: она похожа на яркую звёздочку, которая быстро и ровно плывёт по небу.', q: [
    { type: 'input', q: 'В каком году запустили первый модуль станции?', c: 1998 },
    { type: 'input', q: 'Сколько примерно восходов видят космонавты за сутки?', c: 16 },
    { type: 'one', q: 'Зачем космонавты пристёгивают спальные мешки к стене?', a: ['Чтобы было теплее', 'Чтобы не улетать во сне', 'Чтобы мешки не потерялись', 'Так требует командир'], c: 1 },
    { type: 'tf', q: 'Станцию можно увидеть с Земли без телескопа.', c: true } ] },

  { t: 'Тульский самовар', lv: 2, w: 'Самовар — это металлический сосуд для кипячения воды. Внутри него проходит широкая труба. В трубу кладут горящие угли или сосновые шишки, а вода вокруг трубы нагревается и закипает. Снизу у самовара есть краник, через который наливают кипяток, а сверху ставят заварочный чайник. Так заварка всё время остаётся горячей. Название объясняют просто: самовар сам варит, то есть сам кипятит воду. Чтобы угли разгорелись быстрее, огонь раньше раздували старым сапогом, будто кузнечными мехами. Самым известным самоварным городом стала Тула. Здесь самовары делали в мастерских и на фабриках, и появилась поговорка: «В Тулу со своим самоваром не ездят». Так говорят, когда кто-то везёт вещь туда, где её и так много. Самовары бывали самые разные: в виде вазы, бочонка, шара или яйца. Большие самовары вмещали несколько вёдер воды и стояли в трактирах. Маленькие дорожные самовары брали с собой в путешествие. За самоваром собиралась вся семья, пили чай с пряниками и разговаривали. Сегодня в Туле есть музей «Тульские самовары», где можно увидеть много старинных самоваров.', q: [
    { type: 'one', q: 'Что кладут в трубу самовара?', a: ['Лёд', 'Угли или шишки', 'Чайные листья', 'Сахар'], c: 1 },
    { type: 'one', q: 'Что значит поговорка «В Тулу со своим самоваром не ездят»?', a: ['В Туле запрещены самовары', 'Самовары нельзя возить в поезде', 'Не нужно везти вещь туда, где её и так много', 'В Туле не пьют чай'], c: 2 },
    { type: 'tf', q: 'Сверху на самовар ставили заварочный чайник.', c: true },
    { type: 'one', q: 'Где стояли большие самовары?', a: ['В трактирах', 'На кораблях', 'В школах', 'В лесных избушках'], c: 0 } ] },

  { t: 'Зачем нам сон', lv: 3, w: 'Почти треть жизни человек проводит во сне. Может показаться, что это пустая трата времени, но учёные доказали обратное: сон необходим телу и особенно мозгу. Сон состоит из повторяющихся циклов, каждый длится около полутора часов. В каждом цикле есть глубокий медленный сон и так называемый быстрый сон. Во время глубокого сна тело отдыхает и восстанавливается, а у детей в это время особенно активно вырабатывается гормон роста. Во время быстрого сна глаза под закрытыми веками быстро двигаются, мозг работает почти как днём, и именно тогда чаще всего снятся яркие сны. Пока мы спим, мозг разбирает впечатления дня: важное переносит в долговременную память, а лишнее отбрасывает. Поэтому то, что ты выучил вечером, часто лучше вспоминается утром. Если же человек не выспался, ему труднее сосредоточиться, он хуже запоминает новое, легче раздражается и чаще ошибается. Животные тоже спят, но очень по-разному. Коала может спать до двадцати часов в сутки, а жираф — всего несколько часов, причём часто стоя. Дельфины спят по очереди половинками мозга, чтобы не забыть всплыть и вдохнуть воздух. Сколько нужно спать людям? Это зависит от возраста. Врачи советуют детям от шести до двенадцати лет спать от 9 до 12 часов, а взрослым — от семи до девяти. Чтобы быстрее заснуть, полезно ложиться в одно и то же время, проветривать комнату и откладывать телефон и планшет хотя бы за час до сна: яркий экран мешает мозгу понять, что наступила ночь.', q: [
    { type: 'input', q: 'Сколько часов сна как минимум советуют детям от 6 до 12 лет?', c: 9 },
    { type: 'one', q: 'Когда чаще всего снятся яркие сны?', a: ['Во время глубокого сна', 'Во время быстрого сна', 'Сразу после пробуждения', 'Сны снятся только днём'], c: 1 },
    { type: 'tf', q: 'Один цикл сна длится около полутора часов.', c: true },
    { type: 'one', q: 'Почему телефон лучше отложить за час до сна?', a: ['Он может разрядиться', 'Яркий экран мешает мозгу понять, что наступила ночь', 'Чтобы не разбудить соседей', 'Чтобы он остыл'], c: 1 } ] },

  { t: 'Город на Неве', lv: 3, w: 'Санкт-Петербург основал царь Пётр Первый в 1703 году. Он мечтал о городе-порте, через который Россия сможет торговать с Европой по морю. Место выбрали непростое: устье реки Невы, где она впадает в Финский залив Балтийского моря. Здесь было много болот и островов, поэтому строить приходилось на сваях — деревянных столбах, которые вбивали глубоко в мокрую землю. Первой постройкой города стала Петропавловская крепость на Заячьем острове. С её стены до сих пор каждый день ровно в полдень стреляет пушка, и горожане сверяют по ней часы. Сегодня Петербург стоит на десятках островов, а по городу текут реки и каналы. Через них переброшено множество мостов. Из-за этого Петербург часто называют Северной Венецией — в честь итальянского города на воде. Самые знаменитые — разводные мосты через Неву. Днём по ним ездят машины и ходят люди, а ночью, когда движение стихает, середину моста поднимают вверх. В открывшийся проход проплывают большие корабли. Разводят мосты не круглый год, а только когда Нева свободна ото льда, — примерно с апреля по ноябрь. Посмотреть на это зрелище собираются толпы туристов. Одним из символов города стал Дворцовый мост рядом с Эрмитажем. За свою историю город успел побывать Петроградом и Ленинградом, а в 1991 году ему вернули прежнее имя. Летом в Петербурге бывают белые ночи. Город находится так далеко на севере, что в июне солнце уходит за горизонт совсем ненадолго и неглубоко, и ночь остаётся светлой. В это время на улице можно читать книгу почти без фонаря.', q: [
    { type: 'input', q: 'В каком году основан Санкт-Петербург?', c: 1703 },
    { type: 'one', q: 'Почему Петербург называют Северной Венецией?', a: ['Там всегда тепло', 'Там много рек, каналов и мостов', 'Его построили итальянцы', 'Там делают стекло'], c: 1 },
    { type: 'tf', q: 'Мосты через Неву разводят круглый год.', c: false },
    { type: 'one', q: 'Зачем ночью разводят мосты?', a: ['Чтобы почистить их', 'Чтобы машины отдохнули', 'Чтобы прошли большие корабли', 'Чтобы проветрить реку'], c: 2 } ] },

  { t: 'Таблица Менделеева', lv: 3, w: 'Всё вокруг — вода, воздух, камни и даже наше тело — состоит из химических элементов. Кислород, водород, железо, золото, углерод — всё это элементы. В середине девятнадцатого века учёные знали больше шестидесяти элементов, но никак не могли понять, есть ли между ними порядок. Они казались случайным набором. Русский химик Дмитрий Иванович Менделеев много лет думал над этой загадкой. Он записал сведения о каждом элементе на отдельную карточку и раскладывал карточки, как пасьянс, по весу атомов и по свойствам. В 1869 году он увидел закономерность: если расположить элементы по возрастанию атомного веса, их свойства повторяются через определённые промежутки. Так появилась периодическая таблица. Самое смелое в работе Менделеева — пустые клетки. Учёный понял, что некоторые элементы ещё просто не открыты, и оставил для них места. Более того, он заранее описал, какими они будут. Многие тогда сомневались. Но через несколько лет учёные открыли галлий, потом скандий и германий, и их свойства почти точно совпали с предсказаниями Менделеева! После этого таблицу признали во всём мире. Менделеев был не только химиком. Он изучал нефть, занимался сельским хозяйством, точными мерами и весами, а в 1887 году в одиночку поднялся на воздушном шаре, чтобы наблюдать солнечное затмение. Существует легенда, будто таблица приснилась Менделееву. Сам учёный в ответ говорил, что думал над ней, может быть, двадцать пять лет. Сегодня в таблице больше ста элементов, и один из них назван в честь учёного — менделевий.', q: [
    { type: 'input', q: 'В каком году Менделеев открыл закономерность и создал таблицу?', c: 1869 },
    { type: 'one', q: 'Зачем Менделеев оставил в таблице пустые клетки?', a: ['Чтобы таблица была красивой', 'Для элементов, которые ещё не открыты', 'По ошибке', 'Для своих заметок'], c: 1 },
    { type: 'one', q: 'Какой элемент назван в честь учёного?', a: ['Германий', 'Галлий', 'Скандий', 'Менделевий'], c: 3 },
    { type: 'tf', q: 'Сам Менделеев говорил, что таблица ему просто приснилась.', c: false } ] },

  { t: 'Плесень, которая спасает жизни', lv: 3, w: 'В 1928 году британский учёный Александр Флеминг изучал бактерии — крошечных микробов, которые вызывают болезни. Он выращивал их в плоских стеклянных чашках с крышкой. Такие чашки называют чашками Петри — по фамилии немецкого учёного, который их придумал. Перед отпуском Флеминг оставил несколько чашек на столе. Когда он вернулся, то заметил, что в одну чашку попала плесень — пушистый зеленоватый грибок. Вокруг пятна плесени бактерии погибли, будто их кто-то стёр. Другой бы просто выбросил испорченную чашку, но Флеминг был внимательным исследователем. Позже он говорил, что вовсе не собирался совершить переворот в медицине, — просто заметил то, мимо чего другие прошли бы. Он понял, что плесень выделяет вещество, которое убивает бактерии, и назвал его пенициллином — по латинскому названию этой плесени. Однако получить чистое лекарство оказалось очень трудно. Только через десять с лишним лет другие учёные, Говард Флори и Эрнст Чейн, научились выделять пенициллин в достаточном количестве. Во время Второй мировой войны лекарство спасло множество раненых. В 1945 году Флеминг, Флори и Чейн получили за своё открытие Нобелевскую премию. В нашей стране лекарство из плесени в годы войны создала микробиолог Зинаида Ермольева. Пенициллин стал первым антибиотиком. Так называют лекарства, которые борются с бактериями. Но важно знать: против вирусов, например простуды и гриппа, антибиотики не помогают. Принимать их можно только по назначению врача, иначе бактерии привыкают к лекарству, и оно перестаёт действовать. Эта история учит: в науке важно внимательно наблюдать и не выбрасывать «неудачный» опыт, пока не разберёшься, что случилось.', q: [
    { type: 'input', q: 'В каком году Флеминг заметил плесень в чашке?', c: 1928 },
    { type: 'one', q: 'Что такое антибиотики?', a: ['Лекарства от любых вирусов', 'Витамины', 'Лекарства, которые борются с бактериями', 'Средства от плесени на стенах'], c: 2 },
    { type: 'tf', q: 'Антибиотики помогают от гриппа и простуды.', c: false },
    { type: 'input', q: 'В каком году учёные получили Нобелевскую премию за пенициллин?', c: 1945 } ] },

  { t: 'Амурский тигр', lv: 3, w: 'Амурский тигр — один из самых крупных тигров на планете и самый северный из них. Живёт он на Дальнем Востоке России, в тайге Приморского и Хабаровского краёв. Зимы там снежные и морозные, поэтому у амурского тигра густой длинный мех, а на животе — толстый слой жира, который защищает от холода. Широкие мягкие лапы работают как снегоступы и не дают проваливаться в сугробы. Он отлично плавает и не боится воды, а вот по деревьям взрослые тигры почти не лазают — слишком тяжелы. Тигрята рождаются слепыми и около двух лет живут с мамой, которая учит их охотиться. Взрослый тигр — одиночка. У каждого взрослого зверя есть свой огромный участок, который он обходит и метит. Охотится тигр в основном на оленей и кабанов: подкрадывается бесшумно и нападает из засады. За один раз он может съесть очень много мяса, а потом несколько дней не охотиться. Полоски у каждого тигра свои, и двух одинаковых узоров не бывает, как не бывает одинаковых отпечатков пальцев у людей. По этим узорам учёные узнают зверей на снимках фотоловушек — камер, которые сами срабатывают, когда мимо проходит животное. В середине прошлого века амурских тигров почти не осталось: их было всего несколько десятков. Охоту на тигров запретили, создали заповедники, и постепенно зверей стало больше. По подсчётам 2022 года, в России живёт около 750 амурских тигров. Этот вид занесён в Красную книгу и находится под охраной. А во Владивостоке каждую осень празднуют День тигра.', q: [
    { type: 'input', q: 'Сколько амурских тигров живёт в России по подсчётам 2022 года?', c: 750 },
    { type: 'one', q: 'Зачем учёным фотоловушки?', a: ['Чтобы ловить тигров', 'Чтобы узнавать тигров по узору полосок на снимках', 'Чтобы пугать тигров', 'Чтобы кормить тигров'], c: 1 },
    { type: 'tf', q: 'Амурские тигры живут и охотятся большими стаями.', c: false },
    { type: 'one', q: 'На кого в основном охотится амурский тигр?', a: ['На рыбу', 'На птиц', 'На оленей и кабанов', 'На зайцев'], c: 2 } ] },
]);
